// TASKS.csv #3429 — the lithology thesaurus's second source: rock names from the dh2loop project's hierarchical thesaurus (MIT), read after GeoStrix's own entries. The
// generated file's shape, its credit line, that GeoStrix's own words win, and that a rock only the second source has is read. Synthetic text only.
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { DH2LOOP } from "../src/lib/lithoThesaurusDh2loop.js";
import { THESAURUS, tablesOf } from "../src/lib/lithoThesaurus.js";
import { matchRock } from "../src/lib/lithoHarmonize.js";

const norm = (s) => String(s ?? "").toLowerCase().replace(/[^a-z\s]+/g, " ").replace(/\s+/g, " ").trim();
const FAMILIES = new Set(["volcanic", "intrusive", "sedimentary", "metamorphic", "structure"]);

test("#3429 the add-on: [name, family, words], families GeoStrix has, nothing GeoStrix's own thesaurus already says, no generic last words", () => {
  assert.ok(DH2LOOP.length > 100, String(DH2LOOP.length));
  const own = new Set();
  for (const [n, , s] of THESAURUS) { own.add(norm(n)); for (const w of s) own.add(norm(w)); }
  const lastOwn = new Set([...own].map((k) => k.split(" ").pop()));
  const names = new Set();
  for (const [name, family, words] of DH2LOOP) {
    assert.ok(typeof name === "string" && Array.isArray(words)); assert.ok(FAMILIES.has(family), `${name}: ${family}`);
    const k = norm(name); assert.ok(!own.has(k), `${name} is GeoStrix's already`); assert.ok(!lastOwn.has(k.split(" ").pop()), `${name} ends in a rock GeoStrix has (it would change the last-noun reading)`);
    assert.ok(!names.has(k), `${name} twice`); names.add(k);
    for (const w of words) assert.ok(!own.has(norm(w)) && norm(w) !== k && norm(w).length >= 4, `${name}: ${w}`);
  }
});

test("#3429 a rock only the second source has is read; GeoStrix's own reading of a qualified name is unchanged", () => {
  const T = tablesOf();
  assert.equal(T.words.get("trondhjemite")?.rock, "Trondhjemite"); assert.equal(T.words.get("trondhjemite")?.family, "intrusive"); assert.equal(T.words.get("trondhjemite")?.source, "dh2loop");
  assert.equal(matchRock("fine grained trondhjemite")?.rock, "Trondhjemite");
  assert.equal(T.words.get("basalt")?.source, undefined); // GeoStrix's own entry
  assert.equal(matchRock("basaltic andesite")?.rock, "Andesite"); // the last noun still wins
});

test("#3429 the generated file carries its source, licence and copyright; the build script reads one file and writes no definitions", () => {
  const f = readFileSync(new URL("../src/lib/lithoThesaurusDh2loop.js", import.meta.url), "utf8");
  assert.match(f, /Loop3D\/dh2loop v1\.0\.0/); assert.match(f, /MIT licence, Copyright \(c\) 2020 Mark Jessell/); assert.match(f, /GENERATED by scripts\/samples\/build-dh2loop-thesaurus\.mjs/);
  assert.doesNotMatch(f.split("export const DH2LOOP")[1], /definition/i); // the data part carries no definitions
  const s = readFileSync(new URL("../scripts/samples/build-dh2loop-thesaurus.mjs", import.meta.url), "utf8");
  assert.match(s, /thesaurus_geology_hierarchical\.csv/); assert.doesNotMatch(s, /lithology_code\.csv/);
});

test("#3429 the source is credited: the licences list carries the MIT text, PRIVACY.md names the source", async () => {
  const { bundledData } = await import("../scripts/third-party-licenses.mjs");
  const d = bundledData().find((x) => /dh2loop/.test(x.name));
  assert.ok(d, "listed in bundledData"); assert.equal(d.license, "MIT"); assert.match(d.text, /Copyright \(c\) 2020 Mark Jessell/); assert.match(d.text, /Permission is hereby granted/);
  const p = readFileSync(new URL("../PRIVACY.md", import.meta.url), "utf8");
  assert.match(p, /github\.com\/Loop3D\/dh2loop/); assert.match(p, /MIT licence, Copyright \(c\) 2020 Mark Jessell/);
});
